-- =====================================================================================================
-- 90_VERIFY.sql — SCP0100 클라우드 이관(DB 만) 적용 후 검증 · 조회 전용 · 전체 F5 1회
-- SOURCE-FRESH: 기대값 = 사내 ZIOUI1(localhost) 2026-10-30 16:17:24 실측 (값 단언 형식 — 건수만 보지 않는다)
-- =====================================================================================================

-- [V1] PLAN_TYPE 3행 값 단언 — 기대: 3행 모두 JUDGE='OK' (값 컬럼 전부 사내와 동일)
SELECT 'V1' STEP, S.SHEET_NAME, CASE WHEN T.PROGRAM_ID IS NULL THEN '** MISSING **' WHEN (
       NVL(T.COLUMN_LABEL_NAME,'~') = NVL(S.COLUMN_LABEL_NAME,'~')
       AND NVL(T.SORT_ORDER_NO,-99999) = NVL(S.SORT_ORDER_NO,-99999)
       AND NVL(T.DATA_SORT_METHOD_CODE,'~') = NVL(S.DATA_SORT_METHOD_CODE,'~')
       AND NVL(T.SMALL_CLASS_LABEL_NAME,'~') = NVL(S.SMALL_CLASS_LABEL_NAME,'~')
       AND NVL(T.LARGE_CLASS_LABEL_NAME,'~') = NVL(S.LARGE_CLASS_LABEL_NAME,'~')
       AND NVL(T.FIXED_FLAG,'~') = NVL(S.FIXED_FLAG,'~')
       AND NVL(T.COLUMN_WIDTH,-99999) = NVL(S.COLUMN_WIDTH,-99999)
       AND NVL(T.CELL_CONTROL_OBJECT_TYPE_CODE,'~') = NVL(S.CELL_CONTROL_OBJECT_TYPE_CODE,'~')
       AND NVL(T.CELL_COMBO_DATA_TYPE,'~') = NVL(S.CELL_COMBO_DATA_TYPE,'~')
       AND NVL(T.DATA_SCALE_NUMBER,-99999) = NVL(S.DATA_SCALE_NUMBER,-99999)
       AND NVL(T.DATA_MAX_LENGTH,-99999) = NVL(S.DATA_MAX_LENGTH,-99999)
       AND NVL(T.HORIZONTAL_ALIGN_CODE,'~') = NVL(S.HORIZONTAL_ALIGN_CODE,'~')
       AND NVL(T.UPPERCASE_APPLY_FLAG,'~') = NVL(S.UPPERCASE_APPLY_FLAG,'~')
       AND NVL(T.VISIBLE_FLAG,'~') = NVL(S.VISIBLE_FLAG,'~')
       AND NVL(T.DIVISION_ID,'~') = NVL(S.DIVISION_ID,'~')
       AND NVL(T.DEFAULT_FLAG,'~') = NVL(S.DEFAULT_FLAG,'~')
       AND NVL(T.USER_SELECTABLE_FLAG,'~') = NVL(S.USER_SELECTABLE_FLAG,'~')
       AND NVL(T.VALID_YN,'~') = NVL(S.VALID_YN,'~')
       AND NVL(T.ATTRIBUTE1,'~') = NVL(S.ATTRIBUTE1,'~')
       AND NVL(T.ATTRIBUTE2,'~') = NVL(S.ATTRIBUTE2,'~')
       AND NVL(T.ATTRIBUTE3,'~') = NVL(S.ATTRIBUTE3,'~')
       AND NVL(T.ATTRIBUTE4,'~') = NVL(S.ATTRIBUTE4,'~')
       AND NVL(T.ATTRIBUTE5,'~') = NVL(S.ATTRIBUTE5,'~')
       AND NVL(T.ATTRIBUTE6,'~') = NVL(S.ATTRIBUTE6,'~')
       AND NVL(T.ATTRIBUTE7,'~') = NVL(S.ATTRIBUTE7,'~')
       AND NVL(T.ATTRIBUTE8,'~') = NVL(S.ATTRIBUTE8,'~')
       AND NVL(T.ATTRIBUTE9,'~') = NVL(S.ATTRIBUTE9,'~')
       AND NVL(T.ATTRIBUTE10,'~') = NVL(S.ATTRIBUTE10,'~')
       AND NVL(T.INPUT_TP_CD,'~') = NVL(S.INPUT_TP_CD,'~')
       ) THEN 'OK' ELSE 'VALUE DIFF' END JUDGE, T.CREATED_BY, T.LAST_UPDATED_BY
  FROM (
       SELECT 'SCP0100' PROGRAM_ID, 'REPORT' SHEET_NAME, 'PLAN_TYPE' COLUMN_NAME, 'Plan Type' COLUMN_LABEL_NAME, 15 SORT_ORDER_NO, 'ASC' DATA_SORT_METHOD_CODE, 'Div' SMALL_CLASS_LABEL_NAME, 'Div' LARGE_CLASS_LABEL_NAME, '-' FIXED_FLAG, 80 COLUMN_WIDTH, NULL CELL_CONTROL_OBJECT_TYPE_CODE, NULL CELL_COMBO_DATA_TYPE, NULL DATA_SCALE_NUMBER, NULL DATA_MAX_LENGTH, 'C' HORIZONTAL_ALIGN_CODE, '-' UPPERCASE_APPLY_FLAG, 'Y' VISIBLE_FLAG, NULL DIVISION_ID, 'Y' DEFAULT_FLAG, 'Y' USER_SELECTABLE_FLAG, 'Y' VALID_YN, NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5, NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10, 'S' INPUT_TP_CD FROM DUAL
       UNION ALL SELECT 'SCP0100' PROGRAM_ID, 'SEARCH_LEVEL' SHEET_NAME, 'PLAN_TYPE' COLUMN_NAME, 'Plan Type' COLUMN_LABEL_NAME, 15 SORT_ORDER_NO, 'ASC' DATA_SORT_METHOD_CODE, 'Plan Type' SMALL_CLASS_LABEL_NAME, 'Plan Type' LARGE_CLASS_LABEL_NAME, '-' FIXED_FLAG, 80 COLUMN_WIDTH, NULL CELL_CONTROL_OBJECT_TYPE_CODE, NULL CELL_COMBO_DATA_TYPE, NULL DATA_SCALE_NUMBER, NULL DATA_MAX_LENGTH, 'C' HORIZONTAL_ALIGN_CODE, '-' UPPERCASE_APPLY_FLAG, 'Y' VISIBLE_FLAG, NULL DIVISION_ID, 'Y' DEFAULT_FLAG, 'Y' USER_SELECTABLE_FLAG, 'Y' VALID_YN, NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5, NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10, 'S' INPUT_TP_CD FROM DUAL
       UNION ALL SELECT 'SCP0100' PROGRAM_ID, 'SEARCH_LEVEL_DETAIL' SHEET_NAME, 'PLAN_TYPE' COLUMN_NAME, 'Plan Type' COLUMN_LABEL_NAME, 15 SORT_ORDER_NO, 'ASC' DATA_SORT_METHOD_CODE, 'Plan Type' SMALL_CLASS_LABEL_NAME, 'Plan Type' LARGE_CLASS_LABEL_NAME, '-' FIXED_FLAG, 80 COLUMN_WIDTH, NULL CELL_CONTROL_OBJECT_TYPE_CODE, NULL CELL_COMBO_DATA_TYPE, NULL DATA_SCALE_NUMBER, NULL DATA_MAX_LENGTH, 'C' HORIZONTAL_ALIGN_CODE, '-' UPPERCASE_APPLY_FLAG, 'Y' VISIBLE_FLAG, NULL DIVISION_ID, 'Y' DEFAULT_FLAG, 'Y' USER_SELECTABLE_FLAG, 'Y' VALID_YN, NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5, NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10, 'S' INPUT_TP_CD FROM DUAL
       ) S LEFT JOIN SCM_MGR.SCM_MST_SHEET_COLUMNS T
    ON T.PROGRAM_ID = S.PROGRAM_ID AND T.SHEET_NAME = S.SHEET_NAME AND T.COLUMN_NAME = S.COLUMN_NAME AND NVL(T.DIVISION_ID,'~') = NVL(S.DIVISION_ID,'~')
 ORDER BY S.SHEET_NAME;

-- [V2] SCP0100 시트 메타 총 행수 (기대 36 = 기존 33 + PLAN_TYPE 3) · 논리키 중복 0
SELECT 'V2' STEP, X.TOTAL_ROWS, 36 EXPECTED, CASE WHEN X.TOTAL_ROWS = 36 THEN 'OK' ELSE 'DIFF' END JUDGE, D.DUP_KEYS
  FROM (SELECT COUNT(*) TOTAL_ROWS FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100') X,
       (SELECT COUNT(*) DUP_KEYS FROM (SELECT 1 FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' GROUP BY SHEET_NAME, COLUMN_NAME, NVL(DIVISION_ID,'~') HAVING COUNT(*)>1)) D;

-- [V3] CTRL 화이트리스트 단언 (hook #98 §6.1) — SCP0100 전 행: CELL_CONTROL_OBJECT_TYPE_CODE 는 NULL 또는 'FP%' 만. 기대 0행
SELECT 'V3' STEP, SHEET_NAME, COLUMN_NAME, CELL_CONTROL_OBJECT_TYPE_CODE FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' AND CELL_CONTROL_OBJECT_TYPE_CODE IS NOT NULL AND CELL_CONTROL_OBJECT_TYPE_CODE NOT LIKE 'FP%';
-- [V3b] INPUT_TP_CD 분포 (조회 전용 리포트 — 사내 전 행 'S'. 기대: S=36 1행만)
SELECT 'V3b' STEP, INPUT_TP_CD, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' GROUP BY INPUT_TP_CD ORDER BY 1;

-- [V4] 신규 라벨 6행 값 단언 — 기대 6행 JUDGE='OK'
SELECT 'V4' STEP, S.MSG_ID, S.LANG_CD, CASE WHEN T.MSG_ID IS NULL THEN '** MISSING **' WHEN T.MSG_NM = S.MSG_NM AND T.MSG_TP_CD = S.MSG_TP_CD AND T.USE_YN = S.USE_YN THEN 'OK' ELSE 'VALUE DIFF: ' || T.MSG_NM END JUDGE
  FROM (
       SELECT 'LBL01163' MSG_ID, 'CN' LANG_CD, 'Scale' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'LBL01163' MSG_ID, 'EN' LANG_CD, 'Scale' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'LBL01163' MSG_ID, 'KO' LANG_CD, 'Scale' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'LBL01167' MSG_ID, 'CN' LANG_CD, 'A/S' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'LBL01167' MSG_ID, 'EN' LANG_CD, 'A/S' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'LBL01167' MSG_ID, 'KO' LANG_CD, 'A/S' MSG_NM, 'LBL' MSG_TP_CD, 'Y' USE_YN FROM DUAL
       ) S LEFT JOIN SCM_MGR.SCM_ADM_MSG_M T ON T.MSG_ID = S.MSG_ID AND T.LANG_CD = S.LANG_CD
 ORDER BY 2, 3;

-- [V5] 화면 FE 코드 25개 전부 존재 — 기대 0행
SELECT 'V5' STEP, COLUMN_VALUE MISSING_CODE FROM TABLE(SYS.ODCIVARCHAR2LIST('MSG00097', 'LBL01167', 'LBL01163', 'LBL00112', 'MSG00704', 'MSG00703', 'MSG00618', 'LBL01129', 'LBL01073', 'LBL00767', 'LBL00710', 'LBL00690', 'LBL00684', 'LBL00683', 'LBL00605', 'LBL00310', 'LBL00050', 'LBL00049', 'LBL00040', 'LBL00039', 'LBL00023', 'LBL00022', 'LBL00021', 'LBL00012', 'LBL00001')) WHERE COLUMN_VALUE NOT IN (SELECT MSG_ID FROM SCM_MGR.SCM_ADM_MSG_M);

-- [V6] 배선 역추적 — 화면이 부르는 SP 중 없는 것(ARG_CNT 0) 또는 PROC_M 불일치(PROC_M_ROWS <> ARG_CNT) — 기대 0행 (deploy-package-completeness §4.7)
--   (사내 실측: O_RC1·O_RESULT_CURSOR 둘 다 실제 OUT 인자 → PROC_M 행수 = ALL_ARGUMENTS 인자수. P_SCP0100_GET_GLOBAL_PSI_REPORT 19 · P_SCP0100_GET_PLAN_DATE 5 · P_SCP0100_GET_SHEET_CALENDAR_3SPAN 4 · P_SCP0100_GET_SITE 5)
SELECT 'V6' STEP, X.* FROM (
  SELECT B.SHT_NM, B.MNU_BTN_CD, A.API_URL,
         (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M P WHERE P.PROC_NM=A.API_URL) PROC_M_ROWS,
         (SELECT COUNT(*) FROM ALL_ARGUMENTS G WHERE G.OWNER='SCM_MGR' AND G.PACKAGE_NAME=SUBSTR(A.API_URL,1,INSTR(A.API_URL,'.')-1) AND G.OBJECT_NAME=SUBSTR(A.API_URL,INSTR(A.API_URL,'.')+1) AND G.DATA_LEVEL=0 AND G.ARGUMENT_NAME IS NOT NULL) ARG_CNT
    FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B JOIN SCM_MGR.SCM_ADM_API_M A ON A.API_ID=B.API_ID WHERE B.MNU_ID='SCP0100') X
 WHERE X.ARG_CNT = 0 OR X.PROC_M_ROWS <> X.ARG_CNT;

-- [V7] PKG_SCP0100 VALID · 컴파일 오류 0 (이 패키지는 PKG 를 바꾸지 않지만 화면 동작 전제) — 기대: VALID 2행 · ERR 0
SELECT 'V7' STEP, OBJECT_TYPE, STATUS, (SELECT COUNT(*) FROM ALL_ERRORS E WHERE E.OWNER='SCM_MGR' AND E.NAME='PKG_SCP0100') ERR FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME='PKG_SCP0100' ORDER BY 2;
